// TH15 Stage 3 BossCard3 — 夢符「ドリームキャッチャー」/「夢我夢中」 (Dream Catcher).
// Source: st03bs.ecl.txt::BossCard3 (1230-1334) + ::BossCard3_at (1336-1450).
//
// BossCard3_at samples the (clamped) player position and aim angle once per call,
// then emits 50 short laser bars over 100 frames (wait(2) per step). On Hard and
// Lunatic one bouncing bullet is emitted alongside each bar. The outer loop calls
// it twice per cycle with a difficulty wait (320 / 400 on Lunatic) between them.

const TIME_LIMIT: int = 3124;      // 120 opening buffer + 3000 window + 4 startup
const OPENING_BUFFER: int = 120;
const BOSS_HP: int = 2500;         // entry lifeSet(2500)
const TH15_BALL2: int = 432;       // source etSprite type 5 (radius 4)
const LASER_COLOR: int = 6;        // source etSprite(8,6) reused as target laser color
const BAR_LEN: fx = 115.2fx;       // Line judge end = 0.9 * targetLength 128
const BAR_START: fx = 12.8fx;      // Line judge start = 0.1 * targetLength 128
const BAR_WIDTH: fx = 8fx;         // src width 16 -> Line half-height 4 -> target width 8
const BAR_ACTIVE: int = 180;       // OFFSCREEN a=180 max-lifetime
const BAR_SPEED: fx = 0.3fx;       // etSpeed(0, 0.3, 0) base laser speed
const E_STEP_BAM: int = 40503;     // -3.883222 rad per iteration, in BAM
const BULLET_SPEED: fx = 1.0fx;    // Hard/Lunatic etSpeed s0

// Emitter-1 bullets (Hard only) carry src STEP a=1,c=1: re-aim player after 1
// frame; bounce off up/left/right (src BOUNCE a=1,b=13 -> target walls L/R/U=1+2+4).
xformdef BULLET_HARD {
    @1 bounce_arm(7, 1);
    aim_player(0deg);
}
// Lunatic has no STEP; bullets just bounce once.
xformdef BULLET_LUNATIC {
    bounce_arm(7, 1);
}

// One laser bar (src LaserLine). The line slides along its own angle at 0.3 px/f
// for its ~180-frame OFFSCREEN life. Born-length growth is omitted per the common
// birth simplification; the ACCEL that starts after WAIT(180) never activates
// within the 180-frame lifetime (see report).
async sub bar_drive(h: int, x0: fx, y0: fx, ang: angle) {
    var x: fx = x0;
    var y: fx = y0;
    var dx: fx = BAR_SPEED * cos(ang);
    var dy: fx = BAR_SPEED * sin(ang);
    for i in 0..BAR_ACTIVE {
        wait(1);
        x = x + dx;
        y = y + dy;
        if lz_alive(h) == 1 { lz_origin(h, x, y); }
    }
    if lz_alive(h) == 1 { lz_cancel(h); }
}

// src BossCard3_at: clamp player pos to x[-128,128], y[128,384] once, sample
// E0 = ANGLE_PLAYER - pi/2 once, then 50 steps of (laser bar + optional bullet).
sub card3_at() {
    var px: fx = $player_x;
    var py: fx = $player_y;
    var cx: fx = px;
    var cy: fx = py;
    if px >= 128fx { cx = 128fx; } else if px < -128fx { cx = -128fx; }
    if py < 128fx { cy = 128fx; } else if py >= 384fx { cy = 384fx; }
    var e0: angle = aim_player() - 90deg;
    var rank: int = global(GVAR_RANK);
    for k in 0..50 {
        var e: angle = e0 - ((k * E_STEP_BAM) as angle);
        var sx: fx = cx + 64fx * cos(e);
        var sy: fx = cy + 64fx * sin(e);
        var lang: angle = e - 160deg;
        // src laserNew(0,0,128,0,16)+laserOn(0): emitter-0 bar, one per step.
        var h: int = laser(LASER_COLOR, sx, sy, lang, BAR_LEN, BAR_WIDTH, 0, BAR_ACTIVE, 0);
        if lz_alive(h) == 1 {
            lz_start(h, BAR_START);
            spawn bar_drive(h, sx, sy, lang);
        }
        // src etOn(1) only on Hard/Lunatic; one bullet per step.
        if rank >= 2 {
            var a: angle = atan2(py - sy, px - sx);      // src aim mode 4, N=1
            var alpha: angle = (rand(3641)) as angle;    // RANDF * 0.349 rad (~20 deg)
            var bang: angle = a + alpha + 180deg;         // + pi/N
            if rank == 2 {
                _ = fire(TH15_BALL2, 6, sx, sy, BULLET_SPEED, bang, BULLET_HARD, none);
            } else {
                _ = fire(TH15_BALL2, 6, sx, sy, BULLET_SPEED, bang, BULLET_LUNATIC, none);
            }
        }
        wait(2);
    }
}

// src moveRand(30,4,1.0) inside moveLimit(0,144,240,64) i.e. x[-120,120], y[112,176].
// The boss position does not feed the emissions (they anchor to the player), so the
// wander is a simplified in-box drift (see report).
sub wander() {
    var a: angle = (rand(65536)) as angle;
    var nx: fx = $self_x + 15fx * cos(a);
    var ny: fx = $self_y + 15fx * sin(a);
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 112fx { ny = 112fx; }
    if ny > 176fx { ny = 176fx; }
    move_to(30, nx, ny, EASE_QUAD_OUT);
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // src movePosTime(60,4,0,144) from entry (0,128); 60-frame ease.
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);
    wait(64);                                   // src initial time gate to clock 64
    var w: int = 320;
    if global(GVAR_RANK) == 3 { w = 400; }
    loop {
        wait(60);            // src time gate 64->124, re-applied after each loop-back
        card3_at();
        wait(w);
        wander();
        wait(40);
        card3_at();
        wait(w);
        wander();
        wait(40);
    }
}

async sub control() {
    set_invuln(65535);
    set_hitbox(24fx);       // src setHitbox(48,48) -> radius 24 (kept for body collision)
    set_hurtbox(20fx);      // src setHurtbox(40,40) -> radius 20
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, BOSS_HP, 0, 0, 0, control);
    loop { wait(600); }
}
